#!/usr/bin/env python3

import binascii

tn5250data = ""

class TN5250DataStreamParser(object):
    def __init__(self):
        pass

    def parse(self, data):
        Logical_Record_Length = int.from_bytes(data[0:2], byteorder='big')
        Record_Type = int.from_bytes(data[2:4], byteorder='big')
        Reserved = int.from_bytes(data[4:6], byteorder='big')
        Variable_Header_Length = int.from_bytes(data[6:8], byteorder='big')
        Flags = int.from_bytes(data[8:10], byteorder='big')
        Opcode = data[10:12]
        Payload = data[12:]
        print(Logical_Record_Length, Record_Type, Reserved, Variable_Header_Length, Flags, Opcode, Payload)

if __name__ == "__main__":
    data = binascii.unhexlify(tn5250data)
    parser = TN5250DataStreamParser()
    parser.parse(data)